START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106113338_AddBlog') THEN
    CREATE TABLE "BlogCategories" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(100) NOT NULL,
        "Slug" character varying(120) NOT NULL,
        "SortOrder" integer NOT NULL,
        "IsActive" boolean NOT NULL,
        CONSTRAINT "PK_BlogCategories" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106113338_AddBlog') THEN
    CREATE TABLE "BlogSettings" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Title" character varying(100) NOT NULL,
        "Description" character varying(250) NOT NULL,
        "BannerImage" character varying(255),
        CONSTRAINT "PK_BlogSettings" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106113338_AddBlog') THEN
    CREATE TABLE "BlogPosts" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Title" character varying(200) NOT NULL,
        "Slug" character varying(220) NOT NULL,
        "Excerpt" character varying(400) NOT NULL,
        "BodyHtml" text NOT NULL,
        "CoverImage" character varying(255),
        "CoverAlt" character varying(200) NOT NULL,
        "Author" character varying(100) NOT NULL,
        "SeoTitle" character varying(70),
        "SeoDescription" character varying(170),
        "BlogCategoryId" integer,
        "IsPublished" boolean NOT NULL,
        "PublishedAt" timestamp with time zone,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_BlogPosts" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_BlogPosts_BlogCategories_BlogCategoryId" FOREIGN KEY ("BlogCategoryId") REFERENCES "BlogCategories" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106113338_AddBlog') THEN
    INSERT INTO "BlogSettings" ("Id", "BannerImage", "Description", "Title")
    VALUES (1, NULL, 'Çiçeklerin dünyasından ilham, bakım önerileri ve özel günler için fikirler.', 'Blog');
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106113338_AddBlog') THEN
    CREATE UNIQUE INDEX "IX_BlogCategories_Slug" ON "BlogCategories" ("Slug");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106113338_AddBlog') THEN
    CREATE INDEX "IX_BlogPosts_BlogCategoryId" ON "BlogPosts" ("BlogCategoryId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106113338_AddBlog') THEN
    CREATE INDEX "IX_BlogPosts_IsPublished_PublishedAt" ON "BlogPosts" ("IsPublished", "PublishedAt");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106113338_AddBlog') THEN
    CREATE UNIQUE INDEX "IX_BlogPosts_Slug" ON "BlogPosts" ("Slug");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106113338_AddBlog') THEN
    PERFORM setval(
        pg_get_serial_sequence('"BlogSettings"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "BlogSettings") + 1,
            nextval(pg_get_serial_sequence('"BlogSettings"', 'Id'))),
        false);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106113338_AddBlog') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261106113338_AddBlog', '9.0.3');
    END IF;
END $EF$;
COMMIT;

